package com.kai.automusic;
import android.app.*;import android.content.*;import android.os.*;import java.util.*;
public class Schedule extends BroadcastReceiver{
 static PendingIntent alarm(Context c){return PendingIntent.getBroadcast(c,52,new Intent(c,Schedule.class),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 static void plan(Context c){planStop(c);android.content.SharedPreferences p=c.getSharedPreferences("music",0);AlarmManager a=(AlarmManager)c.getSystemService(Context.ALARM_SERVICE);a.cancel(alarm(c));if(!p.getBoolean("scheduleOn",false))return;Calendar now=Calendar.getInstance();Calendar t=(Calendar)now.clone();t.set(Calendar.HOUR_OF_DAY,p.getInt("scheduleHour",19));t.set(Calendar.MINUTE,p.getInt("scheduleMinute",0));t.set(Calendar.SECOND,0);t.set(Calendar.MILLISECOND,0);int days=p.getInt("scheduleDays",127);for(int i=0;i<8;i++){if(t.after(now)&&(days&(1<<(t.get(Calendar.DAY_OF_WEEK)-1)))!=0){try{if(Build.VERSION.SDK_INT<31||a.canScheduleExactAlarms())a.setExactAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,t.getTimeInMillis(),alarm(c));else a.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,t.getTimeInMillis(),alarm(c));}catch(Exception e){a.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,t.getTimeInMillis(),alarm(c));}return;}t.add(Calendar.DATE,1);}}
 static PendingIntent stopAlarm(Context c){return PendingIntent.getBroadcast(c,53,new Intent(c,Schedule.class).setAction("STOP"),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 static void planStop(Context c){android.content.SharedPreferences p=c.getSharedPreferences("music",0);AlarmManager a=(AlarmManager)c.getSystemService(Context.ALARM_SERVICE);PendingIntent pi=stopAlarm(c);a.cancel(pi);if(!p.getBoolean("timedStopOn",false))return;Calendar now=Calendar.getInstance(),t=(Calendar)now.clone();t.set(Calendar.HOUR_OF_DAY,p.getInt("stopHour",4));t.set(Calendar.MINUTE,p.getInt("stopMinute",30));t.set(Calendar.SECOND,0);t.set(Calendar.MILLISECOND,0);if(!t.after(now))t.add(Calendar.DATE,1);try{if(Build.VERSION.SDK_INT<31||a.canScheduleExactAlarms())a.setExactAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,t.getTimeInMillis(),pi);else a.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,t.getTimeInMillis(),pi);}catch(Exception e){a.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,t.getTimeInMillis(),pi);}}
 public void onReceive(Context c,Intent i){plan(c);if("STOP".equals(i.getAction())){if(c.getSharedPreferences("music",0).getBoolean("timedStopOn",false))try{Intent s=new Intent(c,PlayerService.class).setAction("TIMED_STOP");if(Build.VERSION.SDK_INT>=26)c.startForegroundService(s);else c.startService(s);}catch(Exception e){}return;}if(!c.getSharedPreferences("music",0).getBoolean("scheduleOn",false))return;try{Intent s=new Intent(c,PlayerService.class).setAction("SCHEDULE");if(Build.VERSION.SDK_INT>=26)c.startForegroundService(s);else c.startService(s);}catch(Exception e){}}
}